    <script>const support=document.getElementById('support');document.querySelectorAll('[data-support]').forEach(button=>button.addEventListener('click',()=>support.showModal()));document.getElementById('close-support').addEventListener('click',()=>support.close());support.addEventListener('click',event=>{if(event.target===support){const bounds=support.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)support.close();}});document.querySelectorAll('.mobile a').forEach(link=>link.addEventListener('click',()=>document.querySelector('.mobile').open=false));</script>
